        title.update(cx, |input, cx| input.focus(window, cx));
        self.open = Some(OpenStory {
            name: story_name,
            title,
            prompt,
            completion,
            fit: GrowToFit::new(PROMPT_MAX_ROWS),
            highlight,
            spec_input,
            spec_error: None,
            _subscriptions: subscriptions,
        });''')

# --- Methods: adding, removing, rendering citations --------------------------------
sub('''    // --- Steps ---------------------------------------------------------------''', '''    // --- Spec citations ------------------------------------------------------

    /// Adds `text`, a link from the compiled reference and what the story
    /// touches there, or "No match" and what was looked for, to the spec of
    /// the story named so, by hand. A link to a heading that doesn't exist
    /// isn't added, and the open story says why. Whether it was added.
    fn add_citation(&mut self, name: &str, text: &str, cx: &mut Context<Self>) -> bool {
        let Some(citation) = Citation::parse(text) else {
            return false;
        };
        let checked = citation
            .link
            .as_deref()
            .map_or(Ok(()), |link| check_link(link, &self.project_dir));
        if let Err(why) = checked {
            if let Some(open) = &mut self.open {
                open.spec_error = Some(format!("That link wasn't added: {why}."));
            }
            cx.notify();
            return false;
        }
        let Some(story) = self.story_mut(name).filter(|story| story.task.is_none()) else {
            return false;
        };
        if !story.spec.contains(&citation) {
            story.spec.push(citation);
        }
        if let Some(open) = &mut self.open {
            open.spec_error = None;
        }
        self.save_order(cx);
        cx.notify();
        true
    }

    /// Removes the citation at `at` from the story named so.
    fn remove_citation(&mut self, name: &str, at: usize, cx: &mut Context<Self>) {
        let Some(story) = self.story_mut(name).filter(|story| story.task.is_none()) else {
            return;
        };
        if at < story.spec.len() {
            story.spec.remove(at);
        }
        self.save_order(cx);
        cx.notify();
    }

    /// A list of citations, as a card or an open story shows them: each
    /// element's name and section as a link opening the compiled reference
    /// there, with what it touches; a No match muted with a small marker;
    /// with a remove button for the story named `editable`.
    fn render_citations(
        &self,
        key: &str,
        citations: &[Citation],
        editable: Option<&str>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let sent = editable
            .and_then(|name| self.story(name))
            .is_some_and(|story| story.task.is_some());
        let rows = citations.iter().enumerate().map(|(at, citation)| {
            let label = citation.label();
            let link = citation.link.clone();
            let row = h_flex()
                .gap_1p5()
                .items_center()
                .text_xs()
                .min_w_0();
            let row = match link {
                Some(link) => {
                    let project_dir = self.project_dir.clone();
                    let open = self.hooks.open_reference.clone();
                    row.child(Icon::new(IconName::BookOpen).xsmall().text_color(muted))
                        .child(
                            div()
                                .id(SharedString::from(format!("planning-cite-{key}-{at}")))
                                .flex_none()
                                .cursor_pointer()
                                .underline()
                                .text_color(theme.link)
                                .child(label)
                                .on_click(move |_, window, cx| {
                                    let path = link.split('#').next().unwrap_or(&link);
                                    open(project_dir.join(path), window, cx)
                                }),
                        )
                }
                None => row
                    .child(div().text_color(muted).child("∅"))
                    .child(div().flex_none().text_color(muted).child(label)),
            };
            let row = row
                .when(!citation.note.is_empty(), |row| {
                    row.child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_color(muted)
                            .child(format!("— {}", citation.note)),
                    )
                })
                .when_some(editable.filter(|_| !sent), |row, name| {
                    let name = name.to_string();
                    row.child(
                        Button::new(SharedString::from(format!("planning-uncite-{key}-{at}")))
                            .ghost()
                            .xsmall()
                            .icon(IconName::X)
                            .tooltip("Remove this citation")
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.remove_citation(&name, at, cx)
                            })),
                    )
                });
            gpui_kit::TestSupportExt::test_support(
                div().id(SharedString::from(format!("planning-citation-{key}-{at}"))).child(row),
            )
        });
        v_flex()
            .gap_0p5()
            .children(rows)
            .when(citations.is_empty() && editable.is_some(), |list| {
                list.child(div().text_xs().text_color(muted).child("Nothing cited yet."))
            })
            .into_any_element()
    }

    // --- Steps ---------------------------------------------------------------''')

open(p, 'w').write(s)
